def footer():return f'''<section class="contact-band"><div class="wrap"><div><h2>Ihr Zuhause. Unser Handwerk.</h2><p>Erzählen Sie uns von Ihrer Idee. Wir kümmern uns um den nächsten Schritt.</p></div>{btn('Projekt besprechen','kontakt.html','dark')}</div></section><footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand">{brand()}<p>Durchdachte Lösungen für Fenster, Türen und ein gutes Gefühl zu Hause. Persönlich geplant. Sorgfältig montiert.</p></div><div><h3>Unsere Leistungen</h3><ul><li><a href="fenster.html">Fenster</a></li><li><a href="tueren.html">Türen</a></li><li><a href="insektenschutz.html">Insektenschutz</a></li><li><a href="rolllaeden.html">Rollläden</a></li></ul></div><div><h3>2bfensterwerk</h3><ul><li><a href="ueber-uns.html">Über uns</a></li><li><a href="projekte.html">Einblicke ins Handwerk</a></li><li><a href="rechner.html">Projektplaner & Rechner</a></li><li><a href="kontakt.html">Kontakt aufnehmen</a></li></ul></div><div><h3>Wir sind für Sie da</h3><p class="footer-address">Au 21a · 94137 Bayerbach<br><a href="tel:+491775266889">0177 5266889</a><br><a href="mailto:info@2bfensterwerk.de">info@2bfensterwerk.de</a></p></div></div><div class="footer-bottom"><span>© {2026} 2bfensterwerk · Mit Sorgfalt bis ins Detail.</span><div><a href="impressum.html">Impressum</a><a href="datenschutz.html">Datenschutz</a><a href="#main">Nach oben ↑</a></div></div></div></footer><div class="mobile-cta">{btn('Anrufen','tel:+491775266889','ghost','phone')}{btn('Projekt anfragen','kontakt.html')}</div>'''
def faq(items):return '<div class="faq-list">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
FAQ=[('Fenstertausch im bewohnten Haus – geht das?', 'Ja, ein Austausch lässt sich grundsätzlich auch im bewohnten Haus planen. Beim Aufmaß besprechen wir Zugänglichkeit, Schutz der Räume und die Reihenfolge der Arbeiten. Der genaue Ablauf hängt vom Bestand ab.'),('Was kostet mein Vorhaben?', 'Maße, Material, Verglasung, Ausstattung und Einbausituation bestimmen den Preis. Im Projektplaner stellen Sie die wichtigsten Angaben zusammen. Ein belastbares Angebot entsteht nach der Prüfung Ihres Vorhabens und dem Aufmaß.'),('Kann ich Rollläden oder Insektenschutz nachrüsten?', 'Bei vielen Fenstern und Türen ist das möglich. Entscheidend sind der verfügbare Platz, die Befestigung und die Bedienung. Wir prüfen vor Ort, welche Lösung zu Ihrem Bestand passt.'),('In welcher Region sind Sie tätig?', 'Unser Standort ist Bayerbach im Landkreis Rottal-Inn. Wir betreuen Vorhaben in der Umgebung, unter anderem in Bad Birnbach, Bad Griesbach, Pfarrkirchen und Richtung Passau. Fragen Sie Ihren Projektort gern direkt an.')]
SERVICES=[('Fenster','fenster','window','fenster-anthrazit-innen','Anthrazitfarbenes Fenster in einer bestehenden Fassade','Mehr Tageslicht. Weniger Wärmeverlust. Fenster, die zu Ihrem Zuhause passen.'),('Türen','tueren','door','haustuer-weiss','Weiße Haustür mit Glaselementen','Ein guter erster Eindruck. Und das sichere Gefühl, angekommen zu sein.'),('Insektenschutz','insektenschutz','bug','terrassentuer-festverglasung','Fenster und Terrassentür mit Blick ins Freie','Die frische Luft bleibt. Ungebetene Gäste bleiben draußen.'),('Rollläden','rolllaeden','blind','terrasse-rollladen','Terrasse mit Rollläden an den Fenstern','Licht, Schatten und Privatsphäre. Genau so, wie Sie es mögen.')]
