def planner():return f'''<section class="section project-panel" id="projektplaner"><div class="wrap planner-layout"><div class="planner-intro reveal"><p class="eyebrow bronze">Von der Idee zum Projekt</p><h2 class="display">Ihr Vorhaben.<br>Der erste Schritt.</h2><p class="copy">Vier Produkte. Viele Möglichkeiten. Stellen Sie Ihr Projekt in wenigen Schritten zusammen – als Grundlage für unser persönliches Gespräch.</p><div class="planner-benefits"><span>{icon('check')}Unverbindlich</span><span>{icon('check')}Ohne Registrierung</span></div></div><div class="planner reveal" data-planner><noscript><p class="planner-sub">Für den Projektplaner benötigen Sie JavaScript. <a href="kontakt.html">Hier können Sie uns direkt kontaktieren.</a></p></noscript><div class="planner-progress" aria-label="Planungsschritte"><span class="active" data-progress="0"><b>01</b> Ihr Vorhaben</span><span data-progress="1"><b>02</b> Ihre Details</span><span data-progress="2"><b>03</b> Übersicht</span></div><div data-step="0"><h3>Was dürfen wir für Sie tun?</h3><p class="planner-sub">Wählen Sie den Schwerpunkt Ihres Projekts.</p><div class="choice-grid">{''.join(f'<button type="button" class="choice" data-product="{title}" aria-pressed="{str(i==0).lower()}">{icon(ic)}{title}</button>' for i,(title,slug,ic,img,alt,desc) in enumerate(SERVICES))}</div></div><div data-step="1" hidden><h3>Ein paar Details zu Ihrer Idee.</h3><p class="planner-sub">Ungefähre Maße genügen. Das genaue Aufmaß übernehmen wir vor Ort.</p><div class="fields"><label class="field">Breite je Element (cm)<input data-width type="number" min="20" max="600" step="1" value="120" inputmode="decimal"></label><label class="field">Höhe je Element (cm)<input data-height type="number" min="20" max="400" step="1" value="140" inputmode="decimal"></label><label class="field">Anzahl gleicher Elemente<input data-quantity type="number" min="1" max="100" value="1" step="1" inputmode="numeric"></label><label class="field">Ihr Vorhaben<select data-context><option>Modernisierung</option><option>Neubau</option><option>Nachrüstung</option><option>Noch offen – bitte beraten</option></select></label></div></div><div data-step="2" hidden><h3>Die Basis für Ihr neues Zuhause.</h3><p class="planner-sub">Diese Angaben nehmen Sie direkt in Ihre Anfrage mit.</p><div class="planner-summary" data-summary aria-live="polite"></div></div><p class="planner-error" role="alert"></p><div class="planner-controls"><button class="planner-back" type="button" data-back hidden>← Zurück</button><span class="planner-step-label" data-step-label>Schritt 1 von 3</span><button class="btn btn-bronze" type="button" data-next>Weiter{icon('arrow')}</button><a class="btn btn-bronze" href="kontakt.html" data-inquiry hidden>Beratung anfragen{icon('arrow')}</a></div></div></div></section>'''
def process():return f'''<section class="section"><div class="wrap">{section_head('Ein guter Ablauf. Ein gutes Ergebnis.','Von Anfang an<br>in guten Händen.','<p class="copy">Wir machen aus vielen einzelnen Entscheidungen einen klaren Weg zu Ihrem fertigen Projekt.</p>')}<div class="process-grid">{''.join(f'<article class="process-item reveal"><span class="num">0{i+1}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate([('Zuhören & beraten','Sie erzählen, was Sie vorhaben. Wir fragen nach und besprechen passende Möglichkeiten.'),('Prüfen & planen','Beim Aufmaß schauen wir genau hin. Danach erhalten Sie ein Angebot mit klar beschriebenen Leistungen.'),('Liefern & montieren','Wir stimmen den Termin mit Ihnen ab, schützen den Arbeitsbereich und bauen die Elemente sorgfältig ein.'),('Prüfen & übergeben','Gemeinsam kontrollieren wir die Funktion. Sie erfahren, wie Sie Ihre neuen Elemente bedienen und pflegen.')]) )}</div></div></section>'''
def pagehero(name,title,desc,image=None):
 inner=f'<div><p class="eyebrow">{name}</p><h1 class="display">{title}</h1><p class="copy">{desc}</p><div class="actions">{btn("Persönlich beraten lassen","kontakt.html")}</div></div>'
 if name in ['Impressum','Datenschutz']: inner=inner.replace('<div class="actions">'+btn('Persönlich beraten lassen','kontakt.html')+'</div>','')
 if name=='Kontakt': inner=inner.replace('href="kontakt.html"','href="#anfrage"')
 if name=='Projektplaner & Rechner': inner=inner.replace('Persönlich beraten lassen','Jetzt Projekt planen').replace('href="kontakt.html"','href="#projektplaner"')
 if image:inner='<div class="page-hero-split">'+inner+photo(image[0],image[1],'page-hero-image',False)+'</div>'
 return f'<section class="page-hero"><div class="wrap"><nav class="crumbs" aria-label="Brotkrumen"><a href="index.html">Startseite</a><span>/</span><span>{name}</span></nav>{inner}</div></section>'
