home=f'''<section class="hero"><picture class="hero-picture"><img src="assets/img/architektur-hero.webp" alt="Architekturvisualisierung eines modernen Hauses mit großzügigen Glasflächen in der Abendstimmung" width="1536" height="1024" fetchpriority="high"></picture><div class="wrap hero-content"><p class="eyebrow intro">2bfensterwerk · Bayerbach & Umgebung</p><h1 class="intro">Mehr Licht.<span>Mehr Zuhause.</span></h1><p class="hero-description intro">Fenster, Türen und durchdachter Schutz.<br>Für Räume, in denen Sie sich wohlfühlen.<br>Von der ersten Idee bis zur letzten Schraube.</p><div class="actions intro">{btn('Ihr Projekt beginnt hier','kontakt.html')}{btn('Leistungen entdecken','#leistungen','ghost')}</div></div><div class="wrap hero-bottom"><a class="hero-scroll" href="#leistungen">{icon('down')}Handwerk weiterdenken</a><span class="image-note">Architekturvisualisierung · Gestaltungsidee</span></div><div class="hero-lines" aria-hidden="true"><i></i><i></i><i></i></div></section><section class="trust-strip" aria-label="Unser Anspruch"><div class="wrap trust-grid">{''.join(f'<div class="trust-item">{icon(ic)}<span>{title}<small>{sub}</small></span></div>' for ic,title,sub in [('ruler','Passgenau geplant','Für Ihr Zuhause gemacht'),('craft','Sorgfältig montiert','Handwerk bis ins Detail'),('pin','Persönlich & regional','Aus Bayerbach für die Region'),('shield','Ein Ansprechpartner','Von Beratung bis Übergabe')])}</div></section><section class="section" id="leistungen"><div class="wrap">{section_head('Was wir für Sie tun','Vier Bereiche.<br><em>Ein gutes Zuhause.</em>', '<p class="copy">Mehr Komfort beginnt mit den richtigen Details. Entdecken Sie Lösungen, die Ihren Alltag spürbar besser machen.</p>')}{services()}<div class="services-bottom"><span>Neubau, Modernisierung oder Nachrüstung – wir denken Ihr Vorhaben als Ganzes.</span><a class="text-link" href="leistungen.html">Alle Leistungen ansehen{icon('arrow')}</a></div></div></section>{planner()}<section class="section"><div class="wrap detail-split"><div class="editorial-photo reveal">{photo('fenster-anthrazit-innen','Präzise eingesetztes anthrazitfarbenes Fenster in einer hellen Fassade')}<span class="photo-label">{icon('craft')}Echtes Handwerk. Sichtbare Details.</span></div><div class="reveal"><p class="eyebrow">Qualität steckt im Detail</p><h2 class="display">Gute Fenster sieht man.<br><em>Gute Arbeit spürt man.</em></h2><p class="copy">Ein schönes Element ist der Anfang. Entscheidend ist, wie es zu Ihrem Haus passt – und wie sorgfältig es eingebaut wird.</p><div class="detail-list"><article><span>01</span><div><h3>Beratung mit Blick aufs Ganze.</h3><p>Material, Gestaltung und Nutzung: Wir besprechen, was für Sie zählt, bevor wir eine Lösung empfehlen.</p></div></article><article><span>02</span><div><h3>Das richtige Maß an Präzision.</h3><p>Wir prüfen Öffnungen und Anschlüsse vor Ort. Denn jedes Haus bringt seine eigenen Details mit.</p></div></article><article><span>03</span><div><h3>Montage, die den Unterschied macht.</h3><p>Saubere Anschlüsse, eingestellte Beschläge und eine gemeinsame Funktionsprüfung gehören für uns zusammen.</p></div></article></div><a class="text-link" href="ueber-uns.html">2bfensterwerk kennenlernen{icon('arrow')}</a></div></div></section><section class="section project-gallery"><div class="wrap">{section_head('Einblicke ins Handwerk','Aus Ideen<br>wird Zuhause.', '<a class="text-link" href="projekte.html">Alle Einblicke ansehen'+icon('arrow')+'</a>')}<div class="gallery-grid">{''.join(f'<button class="gallery-item reveal" data-lightbox="assets/img/{im}-1600.webp" data-caption="{t}" type="button" aria-label="{t} – Bild vergrößern">{photo(im,alt)}<div class="gallery-caption"><div><h3>{t}</h3><p>{sub}</p></div><span>{icon("plus")}</span></div></button>' for im,alt,t,sub in [('terrassentuer-festverglasung','Terrassentür und Fenster mit Blick in den Garten','Ein neuer Blick ins Grüne.','Fenster & Terrassentür · Projektaufnahme'),('neubau-haustuer','Dunkle Haustür in einer weißen Neubaufassade','Ankommen beginnt an der Tür.','Haustür · Projektaufnahme')])}</div></div></section>{process()}<section class="section section-soft"><div class="wrap faq-wrap"><div class="reveal"><p class="eyebrow">Gut zu wissen</p><h2 class="display">Gute Fragen.<br>Klare Antworten.</h2><p class="copy">Jedes Zuhause ist anders. Die wichtigsten Fragen können wir trotzdem schon vorab klären.</p><div class="actions"><a class="text-link" href="kontakt.html">Ihre Frage an uns{icon('arrow')}</a></div></div>{faq(FAQ)}</div></section>'''
