for file,(title,desc,body) in PAGES.items():
 fulltitle=title+' | 2bfensterwerk'
 doc=f'''<!doctype html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>{escape(fulltitle)}</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="theme-color" content="#191d19"><link rel="canonical" href="{SITE}/{'index.html' if file=='index.html' else file}"><meta property="og:type" content="website"><meta property="og:locale" content="de_DE"><meta property="og:site_name" content="2bfensterwerk"><meta property="og:title" content="{escape(fulltitle,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{SITE}/{file}"><meta property="og:image" content="{SITE}/assets/img/2bfensterwerk-logo.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="assets/img/favicon.svg" type="image/svg+xml"><link rel="manifest" href="site.webmanifest"><link rel="stylesheet" href="assets/css/site.css"><script src="assets/js/site.js" defer></script></head><body>{header(file)}<main id="main">{body}</main>{footer()}<dialog class="lightbox" aria-label="Vergrößerte Projektaufnahme"><img src="assets/img/fenster-anthrazit-innen-1600.webp" alt=""><div class="lightbox-bar"><span data-lightbox-caption></span><button type="button" class="lightbox-close" aria-label="Großansicht schließen">Schließen ×</button></div></dialog></body></html>'''
 (ROOT/file).write_text(doc)
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{SITE}/{f}</loc></url>\n' for f in PAGES if f!='boeden.html')+'</urlset>\n')
(ROOT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {SITE}/sitemap.xml\n')
print(f'{len(PAGES)} Seiten erstellt.')
